def __getattr__(name: str) -> Any:
    module_path = _LAZY_IMPORTS.get(name)
    if module_path is not None:
        package = __name__ if module_path.startswith('.') else None
        module = import_module(module_path, package)
        value = getattr(module, name)
        globals()[name] = value  # cache so subsequent lookups skip __getattr__
        return value
    # Fall back to treating ``name`` as a submodule (e.g. ``copilotkit.langgraph``),
    # preserving the implicit submodule attributes the previous eager imports
    # created. This keeps ``patch("copilotkit.langgraph.interrupt")`` working.
    try:
        return import_module('.' + name, __name__)
    except ModuleNotFoundError as exc:
        if exc.name == f'{__name__}.{name}':
            raise AttributeError(
                f"module {__name__!r} has no attribute {name!r}"
            ) from None
        raise
